import type { SVGProps } from "react";

type IconProps = SVGProps<SVGSVGElement>;

/* ---- UI icons: one consistent 1.6 stroke, round caps ---- */

function Stroke({ children, ...props }: IconProps) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.6}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      {children}
    </svg>
  );
}

